const PRODUCTS=[
{id:"p01",manufacturer:"CJ제일제당",name:"CJ 맛밤 60g",category:"기타",verificationStatus:"VERIFIED",checkedAt:"2026-09-15",direct:[],facility:[],ingredients:"기존 V2 시연용 표시 데이터",sourceName:"기존 V2 프로토타입 시연 데이터"},
{id:"p02",manufacturer:"오리온",name:"포카칩 오리지널",category:"과자",verificationStatus:"VERIFIED",checkedAt:"2026-09-15",direct:[],facility:[],ingredients:"기존 V2 시연용 표시 데이터",sourceName:"기존 V2 프로토타입 시연 데이터"},
{id:"p03",manufacturer:"농심",name:"포테토칩 오리지널 60g",category:"과자",verificationStatus:"VERIFIED",checkedAt:"2026-09-15",direct:[],facility:["밀"],ingredients:"기존 V2 시연용 표시 데이터",sourceName:"기존 V2 프로토타입 시연 데이터"},
{id:"p04",manufacturer:"시안 데이터",name:"곡물 크래커",category:"과자",verificationStatus:"REVIEW_REQUIRED",checkedAt:null,direct:[],facility:[],ingredients:"표시 정보 수집 전",sourceName:null},
{id:"p05",manufacturer:"시안 데이터",name:"견과 에너지바",category:"에너지바",verificationStatus:"REVIEW_REQUIRED",checkedAt:null,direct:[],facility:[],ingredients:"표시 정보 수집 전",sourceName:null},
{id:"p06",manufacturer:"시안 데이터",name:"과일 에너지바",category:"에너지바",verificationStatus:"REVIEW_REQUIRED",checkedAt:null,direct:[],facility:[],ingredients:"표시 정보 수집 전",sourceName:null},
{id:"p07",manufacturer:"시안 데이터",name:"이온음료",category:"이온음료",verificationStatus:"REVIEW_REQUIRED",checkedAt:null,direct:[],facility:[],ingredients:"표시 정보 수집 전",sourceName:null}
];
const ALLERGENS=["난류","우유","메밀","땅콩","대두","밀","고등어","게","새우","돼지고기","복숭아","토마토","아황산류","호두","닭고기","쇠고기","오징어","조개류","잣"];
const ICONS={home:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 11.5 12 4l9 7.5"/><path d="M5.5 10.5V20h13v-9.5M9.5 20v-6h5v6"/></svg>',search:'<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m15.5 15.5 5 5"/></svg>',card:'<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="5" width="18" height="14" rx="2"/><path d="M3 9h18M7 14h4"/></svg>',user:'<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="8" r="4"/><path d="M4.5 20c.8-4 3.3-6 7.5-6s6.7 2 7.5 6"/></svg>'};
const STORAGE_KEY="meogeodoDwaePrototypeV3";
const defaultState={loggedIn:true,account:{displayName:"현정",email:"demo@local.example"},foodAllergies:["밀","복숭아"],drugReactions:[{id:"d1",drugNameOrIngredient:"나프록센",symptom:"복용 후 두드러기",reactionType:"UNKNOWN"}],searchQuery:"밀가루 안 들어간 간식 찾아줘",category:"전체",profileTab:"food",selectedProductId:"p01"};
function readState(){try{return{...defaultState,...JSON.parse(localStorage.getItem(STORAGE_KEY)||"{}")}}catch{return{...defaultState}}}
let state=readState();const app=document.querySelector("#app");
function saveState(){localStorage.setItem(STORAGE_KEY,JSON.stringify(state))}function route(){return(location.hash||"#home").slice(1).split("?")[0]}function go(to){location.hash=to}function esc(value=""){return String(value).replace(/[&<>'"]/g,ch=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[ch]))}
function toast(message){const el=document.querySelector("#toast");el.textContent=message;el.classList.add("show");clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove("show"),2200)}
function reactionLabel(type){return({ALLERGY:"알레르기",ADVERSE_REACTION:"이상반응",UNKNOWN:"잘 모름"})[type]||"잘 모름"}
function productStatus(product){if(product.verificationStatus==="REVIEW_REQUIRED")return{text:"정보 확인 중",cls:"warn",reason:"근거 출처와 확인일이 없어 추천 및 판정에서 제외합니다."};const direct=product.direct.filter(x=>state.foodAllergies.includes(x));const facility=product.facility.filter(x=>state.foodAllergies.includes(x));if(direct.length)return{text:"직접 함유 표시",cls:"danger",reason:`저장한 항목(${direct.join(", ")})이 알레르기 표시에 있습니다.`};if(facility.length)return{text:"제조환경 확인",cls:"warn",reason:`저장한 항목(${facility.join(", ")})이 제조환경 문구에 있습니다.`};return{text:"표시상 관련 정보 없음",cls:"ok",reason:"확인한 시안 표시 데이터에 저장 항목의 직접 함유·제조환경 문구가 없습니다. 안전 또는 무함유 인증을 뜻하지 않습니다."}}
function productCard(product){const s=productStatus(product);return`<button class="product" data-product="${product.id}"><span><small class="rec-brand">${esc(product.manufacturer||"시안 데이터")}</small><h3>${esc(product.name)}</h3><span class="badge ${s.cls}">${s.text}</span><p>${esc(s.reason)}</p></span><span class="chev">›</span></button>`}
function titleBlock(title,subtitle,back="home"){return`<div class="screen-title"><button class="back" data-go="${back}" aria-label="이전 화면">‹</button><div><h1>${title}</h1><p>${subtitle}</p></div></div>`}
function localNotice(){return`<div class="notice"><span class="notice-icon">i</span><span><strong>프로토타입 저장 안내</strong><br>입력 정보는 이 브라우저의 기기 저장소에만 저장되며 서버로 전송하거나 제3자에게 제공하지 않습니다.</span></div>`}
const screens={login:{code:"SCR-AUTH-001",nav:null,render:renderLogin},signup:{code:"SCR-SIGNUP-001",nav:null,render:renderSignup},home:{code:"SCR-HOME-001",nav:"home",render:renderHome},"all-products":{code:"SCR-PROD-001",nav:"all-products",render:renderAllProducts},results:{code:"SCR-SRCH-001",nav:"all-products",render:renderResults},detail:{code:"SCR-PROD-002",nav:"all-products",render:renderDetail},profile:{code:"SCR-MY-001",nav:"profile",render:renderProfile},card:{code:"SCR-CARD-001",nav:"card",render:renderCard},privacy:{code:"SCR-PRIV-001",nav:"profile",render:renderPrivacy}};
function render(){const key=screens[route()]?route():"home";const screen=screens[key];document.querySelector("#screenCode").textContent=screen.code;const auth=document.querySelector("#authAction");auth.textContent=state.loggedIn?`${state.account.displayName}님 ▾`:"로그인";auth.dataset.go=state.loggedIn?"profile":"login";auth.dataset.action="";document.querySelectorAll("[data-nav]").forEach(btn=>btn.classList.toggle("active",btn.dataset.nav===screen.nav));app.innerHTML=screen.render();app.scrollTop=0;app.focus({preventScroll:true})}
function renderLogin(){return`<div class="stack">${titleBlock("로그인","브라우저 체험 계정으로 개인화 흐름을 확인합니다.","home")}<form class="card stack" id="loginForm"><div class="field"><label for="loginEmail">이메일</label><input id="loginEmail" name="email" type="email" autocomplete="off" value="${esc(state.account.email)}" required></div><div class="field"><label for="loginPassword">비밀번호</label><input id="loginPassword" name="password" type="password" value="demo1234" required minlength="6"><small>입력값은 서버로 보내지 않으며 실제 인증에 사용되지 않습니다.</small></div><button class="primary wide" type="submit">체험 계정으로 로그인</button><button class="secondary wide" type="button" data-go="signup">회원가입 화면 보기</button></form>${localNotice()}</div>`}
function renderSignup(){return`<div class="stack">${titleBlock("회원가입","현재 브라우저에서만 사용하는 체험 계정을 만듭니다.","login")}<div class="notice"><span class="notice-icon">!</span><span><strong>실제 회원가입이 아닙니다.</strong><br>이메일·비밀번호는 서버에 저장되지 않으며, 운영 버전에서는 외부 OIDC/OAuth 인증으로 전환할 설계입니다.</span></div><form class="card stack" id="signupForm"><div class="field"><label for="signupName">이름 또는 별칭</label><input id="signupName" name="displayName" value="이현정" required maxlength="30"></div><div class="field"><label for="signupEmail">이메일</label><input id="signupEmail" name="email" type="email" placeholder="example@email.com" required></div><div class="field"><label for="signupPassword">체험용 비밀번호</label><input id="signupPassword" name="password" type="password" minlength="6" placeholder="6자 이상" required></div><label class="notice"><input name="localConsent" type="checkbox" required><span>현재 브라우저 기기 저장소에 체험 정보를 저장하는 데 동의합니다.</span></label><button class="primary wide" type="submit">브라우저 체험 계정 만들기</button></form></div>`}
function renderHome(){const rec=PRODUCTS.filter(p=>p.verificationStatus==="VERIFIED"&&!p.direct.some(a=>state.foodAllergies.includes(a))).slice(0,3);const recRows=rec.map(p=>{const s=productStatus(p);return`<button class="rec-item" data-product="${p.id}"><span><small class="rec-brand">${esc(p.manufacturer)}</small><strong>${esc(p.name)}</strong></span><span class="rec-status ${s.cls==="warn"?"warn":""}">${s.text}</span></button>`}).join("");return`<div class="stack"><div><p class="eyebrow">내 알레르기: ${state.foodAllergies.join(" · ")||"미등록"}</p><h1>오늘 먹을 간식,<br>표시부터 확인해보세요.</h1></div><form class="search-box" id="searchForm"><input name="q" aria-label="제품 검색" value="${esc(state.searchQuery)}" placeholder="예: 밀가루 안 들어간 간식"><button>찾기</button></form><div class="chips"><button class="chip" data-query="밀 표시 없는 간식">밀 표시 없는 간식</button><button class="chip" data-query="우유 표시 없는 과자">우유 표시 없는 과자</button><button class="chip" data-query="새우 표시 없는 과자">새우 표시 없는 과자</button></div>${state.loggedIn?`<section class="recommend-panel"><div class="recommend-head"><h3>내 알레르기 기준 추천</h3><button class="link-button" data-go="profile">정보 수정</button></div><p>${state.foodAllergies.join(" · ")} 표시를 제외해 골랐어요.</p><div class="rec-list">${recRows}</div><div class="recommend-foot">등록 상품 ${PRODUCTS.length}개 중 함유 표시 ${PRODUCTS.filter(p=>p.direct.some(a=>state.foodAllergies.includes(a))).length}개 제외, 제조환경 확인 ${PRODUCTS.filter(p=>p.facility.some(a=>state.foodAllergies.includes(a))).length}개 포함 · 실제 섭취 전 포장지 재확인</div></section>`:`<div class="card empty"><h3>개인화 추천은 로그인 후 확인</h3><p>브라우저 체험 계정에 저장한 항목을 기준으로 표시를 비교합니다.</p><button class="primary" data-go="login">로그인</button></div>`}<div class="row between"><h2 style="margin:0">‘밀’ 기준 결과</h2><button class="link-button" data-go="all-products">전체 식품 데이터 · ${PRODUCTS.length}개</button></div><div class="notice"><span class="notice-icon">!</span><span>표시가 없다는 사실은 안전·섭취 가능·무함유 인증을 의미하지 않습니다. 현재 포장지를 다시 확인하세요.</span></div></div>`}
function renderAllProducts(){const cats=["전체","과자","에너지바","이온음료","기타"];const counts=Object.fromEntries(cats.slice(1).map(c=>[c,PRODUCTS.filter(p=>p.category===c).length]));const shown=state.category==="전체"?PRODUCTS:PRODUCTS.filter(p=>p.category===state.category);return`<div class="stack">${titleBlock("전체 식품 데이터","검색하지 않고 등록된 시안 제품을 둘러봅니다.","home")}<div class="stats"><div class="stat"><strong>${PRODUCTS.length}</strong><span>총 등록 제품</span></div><div class="stat"><strong>${PRODUCTS.filter(p=>p.verificationStatus==="REVIEW_REQUIRED").length}</strong><span>정보 확인 중</span></div></div><div class="card"><h3>카테고리별 제품 수</h3><div class="chips">${Object.entries(counts).map(([c,n])=>`<span class="chip">${c} ${n}</span>`).join("")}</div></div><div class="chips" role="group" aria-label="카테고리 필터">${cats.map(c=>`<button class="chip ${state.category===c?"active":""}" data-category="${c}">${c}</button>`).join("")}</div><div class="row between"><span class="count-note">${shown.length}개 표시</span><span class="count-note">배열에서 자동 계산</span></div><div class="product-list">${shown.map(productCard).join("")}</div><div class="notice"><span class="notice-icon">i</span><span><strong>화면 설계용 시안 데이터</strong><br>실제 제품 정보가 아닙니다. 정보 확인 중 제품은 개인화 추천과 표시 판정에서 제외됩니다.</span></div></div>`}
function renderResults(){const q=state.searchQuery.toLowerCase();const category=q.includes("과자")?"과자":q.includes("에너지바")?"에너지바":q.includes("이온")?"이온음료":null;const terms=ALLERGENS.filter(a=>q.includes(a)).concat(q.includes("밀가루")?["밀"]:[]).filter((v,i,a)=>a.indexOf(v)===i);const shown=PRODUCTS.filter(p=>!category||p.category===category);return`<div class="stack">${titleBlock("검색 결과",`“${esc(state.searchQuery)}” 조건을 키워드로 해석했습니다.`,"home")}<div class="card tint"><h3>검색어에서 이렇게 이해했어요</h3><div class="chips">${category?`<span class="chip selected">${category}</span>`:""}${terms.map(t=>`<span class="chip selected">제외: ${t}</span>`).join("")||'<span class="count-note">특정 제외 항목 없음</span>'}</div><p style="margin:10px 0 0">실제 LLM이 아닌 JavaScript 키워드 매핑입니다.</p></div><div class="product-list">${shown.map(productCard).join("")||`<div class="card empty"><h3>검색 결과가 없습니다</h3><p>제품 유형이나 제외 항목을 바꿔 보세요.</p><button class="secondary" data-go="home">검색 조건 바꾸기</button></div>`}</div><div class="notice"><span class="notice-icon">!</span><span>표시정보가 없다는 것과 글루텐프리·무알레르기 인증은 다릅니다. 현재 포장지를 반드시 재확인하세요.</span></div></div>`}
function renderDetail(){const p=PRODUCTS.find(x=>x.id===state.selectedProductId)||PRODUCTS[0];const s=productStatus(p);return`<div class="stack">${titleBlock("제품 근거·상세","V2의 표시 확인 구조를 유지한 프로토타입 화면입니다.","all-products")}<div class="detail-hero"><small>${esc(p.manufacturer||"시안 데이터")} · ${p.category}</small><h2>${esc(p.name)}</h2><span class="badge ${s.cls}">${s.text}</span></div><div class="card"><h3>분류 근거</h3><p style="margin:0">${esc(s.reason)}</p></div><div class="card data-rows"><div class="data-row"><span>원재료 시안</span><strong>${esc(p.ingredients)}</strong></div><div class="data-row"><span>직접 함유 표시</span><strong>${p.direct.length?p.direct.join(", "):"시안 데이터상 없음"}</strong></div><div class="data-row"><span>제조환경 문구</span><strong>${p.facility.length?p.facility.join(", "):"시안 데이터상 없음"}</strong></div><div class="data-row"><span>확인일</span><strong>${p.checkedAt||"미확인"}</strong></div><div class="data-row"><span>근거</span><strong>${p.sourceName?`${esc(p.sourceName)}<br><a class="source-link" href="#prototype-source" data-source-link>시안 근거 안내</a>`:"출처 확인 전"}</strong></div></div><div class="notice" id="prototype-source"><span class="notice-icon">i</span><span>기존 V2 화면의 시연 데이터를 이어받은 화면 설계 시안입니다. 운영 데이터로 사용하지 않습니다.</span></div><div class="notice"><span class="notice-icon">!</span><span><strong>섭취 전 확인</strong><br>제품 정보와 제조공정은 바뀔 수 있습니다. 현재 포장지와 제조사 최신 안내를 다시 확인하세요.</span></div></div>`}
function renderProfile(){const food=`<form class="stack" id="foodForm"><div><h3>식품 알레르기 관리</h3><p>국내 알레르기 표시 대상 19개 항목 중 해당 항목을 선택합니다.</p></div><div class="allergen-grid">${ALLERGENS.map(a=>`<label><input type="checkbox" name="allergen" value="${a}" ${state.foodAllergies.includes(a)?"checked":""}><span>${a}</span></label>`).join("")}</div><button class="primary wide">선택 항목 저장</button></form>`;const drug=`<div class="stack"><div><h3>약물 알레르기·이상반응 기록</h3><p>의료진에게 보여주기 위한 사용자 입력 기록이며 진단서가 아닙니다.</p></div>${state.drugReactions.length?state.drugReactions.map(d=>`<div class="reaction-item row between"><span><strong>${esc(d.drugNameOrIngredient)}</strong><small>${reactionLabel(d.reactionType)}${d.symptom?` · ${esc(d.symptom)}`:""}</small></span><button class="link-button" data-delete-reaction="${d.id}">삭제</button></div>`).join(""):'<div class="empty"><p>기록이 없습니다.</p></div>'}<form class="card stack" id="drugForm"><div class="field"><label for="drugName">약물명 또는 주성분</label><input id="drugName" name="drugNameOrIngredient" placeholder="예: 페니실린" required></div><div class="field"><label for="symptom">경험한 증상 (선택)</label><input id="symptom" name="symptom" placeholder="예: 두드러기"></div><div class="field"><label for="reactionType">구분</label><select id="reactionType" name="reactionType"><option value="ALLERGY">알레르기</option><option value="ADVERSE_REACTION">이상반응</option><option value="UNKNOWN" selected>잘 모름</option></select></div><button class="primary wide">기록 추가</button></form><div class="notice"><span class="notice-icon">!</span><span>약물 추천, 대체약 추천, 복용 가능 여부 판단은 제공하지 않습니다.</span></div></div>`;return`<div class="stack"><div class="row between"><div><h1>내 정보</h1><p>검색에 적용할 항목과 보여줄 기록을 관리합니다.</p></div><button class="link-button" data-go="privacy">개인정보 처리 안내</button></div>${localNotice()}<div class="segmented"><button class="${state.profileTab==="food"?"active":""}" data-tab="food">식품 알레르기</button><button class="${state.profileTab==="drug"?"active":""}" data-tab="drug">약물·이상반응</button></div>${state.profileTab==="food"?food:drug}<button class="secondary wide" data-action="logout">체험 계정 로그아웃</button></div>`}
function renderCard(){return`<div class="stack"><div><h1>알레르기 카드</h1><p>병원이나 식당에서 참고용으로 바로 보여주세요.</p></div><div class="pass"><span class="mini">MY ALLERGY CARD · 사용자 입력 정보</span><h2>${esc(state.account.displayName)}</h2><p>현재 브라우저에 저장된 참고 기록</p><div class="pass-section"><span>식품 알레르기</span><strong>${state.foodAllergies.join(", ")||"입력 없음"}</strong></div><div class="pass-section"><span>약물 알레르기·이상반응</span>${state.drugReactions.length?state.drugReactions.map(d=>`<strong>${esc(d.drugNameOrIngredient)} · ${reactionLabel(d.reactionType)}${d.symptom?`<br><small>${esc(d.symptom)}</small>`:""}</strong>`).join("<br>"):"입력 없음"}</div><div class="pass-section"><span>안내</span><strong>본인이 직접 입력한 참고 정보이며 공식 의료기록이나 진단서가 아닙니다.</strong></div></div><button class="primary wide" data-action="enlarge-card">크게 보여주기</button><button class="secondary wide" data-go="profile">정보 수정</button><div class="notice"><span class="notice-icon">i</span><span>친구 추가·자동 공유는 MVP에 포함하지 않습니다. 이 화면은 기기 소유자가 직접 보여주는 용도입니다.</span></div></div>`}
function renderPrivacy(){return`<div class="stack">${titleBlock("개인정보 처리 안내","프로토타입과 향후 운영 서비스의 범위를 구분합니다.","profile")}<div class="card"><h2>현재 프로토타입</h2><ul class="privacy-list"><li>입력 정보는 이 브라우저의 기기 저장소(localStorage)에만 저장됩니다.</li><li>서버 전송 및 제3자 제공이 없습니다.</li><li>브라우저 데이터 삭제 시 정보가 함께 삭제될 수 있습니다.</li><li>공용 기기에서는 민감한 건강 정보 입력을 권장하지 않습니다.</li></ul></div><div class="card tint"><h2>운영 서비스 전환 시 필요</h2><ul class="privacy-list"><li>개인정보 처리방침 및 민감정보 수집·이용 동의</li><li>최소 수집과 목적 제한</li><li>전송·저장 암호화</li><li>OIDC/OAuth 본인 인증과 접근 통제</li><li>보관 기간 및 안전한 파기 정책</li><li>접근·공유 이력 관리</li></ul></div><div class="card"><h2>향후 공유 기능 원칙</h2><ul class="privacy-list"><li>친구 검색과 자동 공유 금지</li><li>사용자가 직접 고른 정보만 공유</li><li>약물 이상반응은 기본 공유 대상에서 제외</li><li>일회성 또는 만료되는 QR·링크</li><li>즉시 철회와 열람 이력 제공</li><li>기본값은 “공유 안 함”</li></ul></div><button class="ghost wide" data-action="clear-local">이 브라우저의 체험 정보 초기화</button></div>`}
function registerWebMcpTools(){
  const context=typeof document==="undefined"?undefined:document.modelContext;
  if(!context?.registerTool)return;
  try{
    void Promise.resolve(context.registerTool({
      name:"set_food_allergies",
      title:"식품 알레르기 항목 저장",
      description:"프로토타입의 개인화 기준으로 사용할 식품 알레르기 항목을 현재 브라우저에 저장하고 화면을 갱신합니다.",
      inputSchema:{type:"object",properties:{allergens:{type:"array",items:{type:"string",enum:ALLERGENS},uniqueItems:true}},required:["allergens"],additionalProperties:false},
      annotations:{readOnlyHint:false,untrustedContentHint:false},
      execute(input){
        if(!input||typeof input!=="object"||!Array.isArray(input.allergens))throw new TypeError("allergens 배열이 필요합니다.");
        const allergens=input.allergens.map(String);
        if(new Set(allergens).size!==allergens.length||allergens.some(item=>!ALLERGENS.includes(item)))throw new TypeError("지원하는 알레르기 항목만 중복 없이 입력해 주세요.");
        state.foodAllergies=allergens;
        saveState();
        render();
        return{foodAllergies:[...state.foodAllergies],storage:"localStorage",serverTransmission:false};
      }
    })).catch(error=>console.warn("WebMCP tool registration failed",error));
  }catch(error){console.warn("WebMCP tool registration failed",error)}
}
document.addEventListener("click",event=>{const goButton=event.target.closest("[data-go]");if(goButton){event.preventDefault();go(goButton.dataset.go);return}const auth=event.target.closest("[data-action='logout']");if(auth){state.loggedIn=false;saveState();toast("브라우저 체험 계정에서 로그아웃했습니다.");go("home");return}const q=event.target.closest("[data-query]");if(q){state.searchQuery=q.dataset.query;saveState();go("results");return}const category=event.target.closest("[data-category]");if(category){state.category=category.dataset.category;saveState();render();return}const product=event.target.closest("[data-product]");if(product){state.selectedProductId=product.dataset.product;saveState();go("detail");return}const tab=event.target.closest("[data-tab]");if(tab){state.profileTab=tab.dataset.tab;saveState();render();return}const del=event.target.closest("[data-delete-reaction]");if(del){state.drugReactions=state.drugReactions.filter(d=>d.id!==del.dataset.deleteReaction);saveState();render();toast("기록을 삭제했습니다.");return}if(event.target.closest("[data-source-link]")){event.preventDefault();document.querySelector("#prototype-source")?.scrollIntoView({behavior:"smooth",block:"center"});return}if(event.target.closest("[data-action='enlarge-card']")){toast("제시용 카드입니다. 공식 의료기록이 아닙니다.");return}if(event.target.closest("[data-action='clear-local']")){localStorage.removeItem(STORAGE_KEY);state={...defaultState,loggedIn:false,foodAllergies:[],drugReactions:[]};toast("이 브라우저의 체험 정보를 초기화했습니다.");render()}});
document.addEventListener("submit",event=>{event.preventDefault();const form=event.target;const data=new FormData(form);if(form.id==="searchForm"){state.searchQuery=String(data.get("q")||"").trim();if(!state.searchQuery)return toast("찾고 싶은 식품이나 제외 항목을 입력해 주세요.");saveState();go("results")}if(form.id==="loginForm"){state.loggedIn=true;state.account.email=String(data.get("email")||state.account.email);saveState();toast("브라우저 체험 계정으로 로그인했습니다.");go("home")}if(form.id==="signupForm"){state.loggedIn=true;state.account={displayName:String(data.get("displayName")||"체험 사용자"),email:String(data.get("email")||"")};saveState();toast("이 브라우저에만 체험 계정을 만들었습니다.");go("profile")}if(form.id==="foodForm"){state.foodAllergies=data.getAll("allergen").map(String);saveState();toast("식품 알레르기 항목을 이 브라우저에 저장했습니다.");render()}if(form.id==="drugForm"){state.drugReactions.push({id:`d${Date.now()}`,drugNameOrIngredient:String(data.get("drugNameOrIngredient")||""),symptom:String(data.get("symptom")||""),reactionType:String(data.get("reactionType")||"UNKNOWN")});saveState();toast("약물 이상반응 기록을 추가했습니다.");render()}});
window.addEventListener("hashchange",render);document.querySelectorAll("[data-icon]").forEach(el=>el.innerHTML=ICONS[el.dataset.icon]);render();registerWebMcpTools();
